import React, { useState, useEffect } from 'react';
import orderService from '../services/orderService';

const ReadyOrders = () => {
  const [orders, setOrders] = useState([]);
  const [fadeOutOrders, setFadeOutOrders] = useState(new Set());
  const [lastUpdateTime, setLastUpdateTime] = useState(Date.now());

  useEffect(() => {
    // Initial load
    setOrders(orderService.getReadyOrders());
    
    // Set up automatic updates every 3 seconds
    const interval = setInterval(() => {
      const previousOrderIds = orders.map(order => order.id);
      
      // Simulate order updates
      orderService.simulateOrderUpdates();
      const newOrders = orderService.getReadyOrders();
      const currentOrderIds = newOrders.map(order => order.id);
      
      // Find orders that were removed
      const removedOrderIds = orderService.getRemovedOrders(currentOrderIds, previousOrderIds);
      
      if (removedOrderIds.length > 0) {
        // Start fade out animation for removed orders
        setFadeOutOrders(new Set(removedOrderIds));
        
        // Remove orders after fade animation completes
        setTimeout(() => {
          setOrders(newOrders);
          setFadeOutOrders(new Set());
        }, 500); // 500ms fade duration
      } else {
        // Just update orders if no removals
        setOrders(newOrders);
      }
      
      setLastUpdateTime(Date.now());
    }, 3000);

    return () => clearInterval(interval);
  }, [orders]);

  return (
    <div className="w-full">
      <h2 className="text-2xl xl:text-6xl font-bold text-black mb-6 text-center">
        Ready Orders
      </h2>
      
      <div className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-4 gap-4 xl:gap-6">
        {readyOrders.map((order) => (
          <div 
            key={order.id} 
            className="bg-white border-2 border-gray-300 rounded-lg p-4 xl:p-6 shadow-md hover:shadow-lg transition-shadow flex-grow flex flex-col"
          >
            {/* Order Header */}
            <div className="flex justify-between items-start mb-3">
              <div className="text-lg xl:text-3xl font-bold text-black">
                {order.orderNumber}
              </div>
              <div className="bg-green-500 text-white px-2 py-1 rounded text-xs xl:text-sm font-semibold">
                READY
              </div>
            </div>

            {/* Customer Name */}
            <div className="text-base xl:text-2xl font-semibold text-gray-800 mb-2">
              {order.customerName}
            </div>

            {/* Items List */}
            <div className="flex-grow mb-3">
              <div className="text-sm xl:text-lg text-gray-600">
                {order.items.map((item, index) => (
                  <div key={index} className="mb-1">
                    • {item}
                  </div>
                ))}
              </div>
            </div>

            {/* Order Footer */}
            <div className="border-t border-gray-200 pt-3 mt-auto">
              <div className="flex justify-between items-center">
                <div className="text-sm xl:text-xl font-semibold text-gray-700">
                  Total: {order.total}
                </div>
                <div className="text-xs xl:text-lg text-gray-500">
                  {order.readyTime}
                </div>
              </div>
            </div>

            {/* Action Button */}
            <button className="w-full mt-3 bg-green-600 hover:bg-green-700 text-white py-2 xl:py-3 rounded-lg font-semibold text-sm xl:text-lg transition-colors">
              Mark as Collected
            </button>
          </div>
        ))}
      </div>
    </div>
  );
};

export default ReadyOrders;
